-- ---------- FLASHCARDS ----------
INSERT INTO flashcards (category_id, front, back) VALUES
(1,'RAM','Random Access Memory. Fast, temporary memory used by running programs. Cleared when power is off.'),
(1,'ROM','Read Only Memory. Permanent memory that holds start-up instructions.'),
(1,'Operating system','Software that manages hardware and runs other programs, for example Windows, Linux or macOS.'),
(1,'Bit and byte','A bit is a single 0 or 1. A byte is 8 bits.'),
(1,'Compiler vs interpreter','A compiler translates the whole program first. An interpreter translates and runs it line by line.'),
(1,'IP address','A number that identifies a device on a network.'),
(2,'DOM','Document Object Model. The page structure that JavaScript can read and change.'),
(2,'GET vs POST','GET sends data in the URL and is for reading. POST sends data in the request body and is for submitting forms.'),
(2,'PDO','PHP Data Objects. A safe way to talk to a database using prepared statements.'),
(2,'Prepared statement','An SQL query with placeholders so user input is never treated as code. Prevents SQL injection.'),
(2,'Responsive design','Layouts that adapt to different screen sizes using flexible units and media queries.'),
(2,'Session','Data the server remembers about a visitor between page loads, linked by a cookie.'),
(3,'Condition','Code that chooses a path using if, else if and else.'),
(3,'Function','A named block of code you can call again and again, optionally with inputs and a return value.'),
(3,'Array','An ordered list of values accessed by index, starting at 0.'),
(3,'Loop','Repeats code. for repeats a set number of times, while repeats until a condition is false.'),
(3,'Event handling','Running code when something happens, such as a click. Use addEventListener.'),
(3,'Modulo (%)','Gives the remainder after division. 10 % 3 equals 1.'),
(4,'Stack','Last In, First Out. Operations: push and pop.'),
(4,'Queue','First In, First Out. Operations: enqueue and dequeue.'),
(4,'Big O notation','Describes how the running time of an algorithm grows as the input grows.'),
(4,'Binary search','Repeatedly halves a sorted list to find a value. O(log n).'),
(4,'Brute force','Try every possible solution and keep the best valid one. Simple but often slow.'),
(4,'Recursion','A function that calls itself on a smaller problem until it reaches a base case.'),
(5,'S.M.A.R.T.','Self-Monitoring, Analysis and Reporting Technology. Reports the health of a drive.'),
(5,'Benchmark','A repeatable test that measures how fast a system performs a task.'),
(5,'SSD vs HDD','SSDs have no moving parts and are faster. HDDs spin magnetic platters and are cheaper per GB.'),
(5,'Cache','Very small, very fast memory close to the CPU that stores recently used data.'),
(5,'Throughput vs latency','Throughput is how much work is done per second. Latency is how long one request takes.'),
(5,'BIOS / UEFI','Firmware that starts the hardware and loads the operating system.'),
(6,'Capital of Ghana','Accra'),
(6,'Largest planet','Jupiter'),
(6,'Speed of light','About 300,000 kilometres per second.'),
(6,'Number of continents','Seven'),
(6,'Chemical symbol for gold','Au'),
(6,'Longest river in Africa','The Nile');
